import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import ApiService from '../../Services/ApiService';

export default function SellerEditProfile() {
    const navigate = useNavigate();
    const fileInputRef = useRef(null);
    const [profileData, setProfileData] = useState({
        firstName: '',
        lastName: '',
        email: '',
        phone: '',
        bio: ''
    });
    const [loading, setLoading] = useState(false);
    const [previewImage, setPreviewImage] = useState(null);
    const [imageLoaded, setImageLoaded] = useState(false);

    useEffect(() => {
        // Initialize Lucide icons
        if (window.lucide) {
            window.lucide.createIcons();
        }
        
        // Load actual user profile data from localStorage
        const loadUserProfile = () => {
            try {
                const storedUser = localStorage.getItem('studioUser');
                if (storedUser) {
                    const user = JSON.parse(storedUser);
                    setProfileData({
                        firstName: user.firstname || '',
                        lastName: user.lastname || '',
                        email: user.email || '',
                        phone: user.telephone || '',
                        bio: user.bio || ''
                    });
                    setPreviewImage(user.image || null);
                    // Mark image as loaded once we have the data
                    if (user.image) {
                        setImageLoaded(true);
                    }
                }
            } catch (error) {
                console.error('Error loading user profile:', error);
                toast.error('Failed to load profile data');
            }
        };
        
        loadUserProfile();
    }, []);

    const handleImageLoad = () => {
        setImageLoaded(true);
    };

    const handleFileChange = async (e) => {
        const file = e.target.files[0];
        if (file) {
            // Validate file type
            if (!file.type.match('image.*')) {
                toast.error('Please select an image file (JPG, PNG, etc.)');
                return;
            }
            
            // Validate file size (5MB max)
            if (file.size > 5 * 1024 * 1024) {
                toast.error('File size exceeds 5MB limit');
                return;
            }
            
            setLoading(true);
            
            try {
                // Upload the profile image to the server
                const response = await ApiService.uploadProfileImage(file);
                
                if (response.success) {
                    // Save the image path to the database
                    const updateResponse = await ApiService.updateProfileImagePath(response.imagePath);
                    if (!updateResponse.success) {
                        toast.error(updateResponse.message || 'Failed to save profile image to database');
                        return;
                    }
                    
                    // Update preview
                    const imageUrl = URL.createObjectURL(file);
                    setPreviewImage(imageUrl);
                    
                    toast.success('Profile picture updated successfully!');
                } else {
                    toast.error(response.message || 'Failed to upload profile picture');
                }
            } catch (error) {
                console.error('Profile image upload error:', error);
                toast.error('Failed to upload profile picture: ' + (error.message || 'Unknown error'));
            } finally {
                setLoading(false);
            }
        }
    };

    const triggerFileSelect = () => {
        if (!loading) {
            fileInputRef.current.click();
        }
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setProfileData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        
        setLoading(true);
        
        try {
            // Update localStorage with the new data
            try {
                const storedUser = localStorage.getItem('studioUser');
                if (storedUser) {
                    const user = JSON.parse(storedUser);
                    const updatedUser = {
                        ...user,
                        firstname: profileData.firstName,
                        lastname: profileData.lastName,
                        email: profileData.email,
                        telephone: profileData.phone,
                        bio: profileData.bio,
                        image: previewImage || user.image
                    };
                    localStorage.setItem('studioUser', JSON.stringify(updatedUser));
                    toast.success('Profile updated successfully!');
                    
                    // Dispatch a custom event to notify other components of the user update
                    window.dispatchEvent(new Event('userUpdated'));
                    
                    // Navigate back to profile page
                    navigate('/studio/seller/profile');
                }
            } catch (error) {
                console.error('Error updating user profile:', error);
                toast.error('Failed to update profile');
            }
        } catch (error) {
            console.error('Profile update error:', error);
            toast.error('Failed to update profile: ' + error.message);
        } finally {
            setLoading(false);
        }
    };

    const handleCancel = () => {
        navigate('/studio/seller/profile');
    };

    const displayName = `${profileData.firstName || ''} ${profileData.lastName || ''}`.trim() || 'Seller';
    // Use the uploaded image if available, otherwise fallback to default
    const profileImageUrl = previewImage || '/assets/images/users/avatar-1.jpg';

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">Edit Profile</h4>
                </div>
            </div>

            {/* Hidden file input */}
            <input
                type="file"
                ref={fileInputRef}
                onChange={handleFileChange}
                accept="image/*"
                style={{ display: 'none' }}
                disabled={loading}
            />

            <div className="col-12">
                <div className="card">
                    <div className="card-body">
                        <form onSubmit={handleSubmit}>
                            <div className="row">
                                {/* Profile Picture Section */}
                                <div className="col-lg-4">
                                    <div className="text-center">
                                        <div className="position-relative d-inline-block">
                                            {/* Hidden default avatar that shows while loading */}
                                            {!imageLoaded && (
                                                <div 
                                                    className="rounded-circle bg-light d-flex align-items-center justify-content-center"
                                                    style={{ width: '150px', height: '150px' }}
                                                >
                                                    <i className="ri-user-line ri-3x text-muted"></i>
                                                </div>
                                            )}
                                            
                                            {/* Profile image with onLoad handler */}
                                            <img 
                                                src={profileImageUrl} 
                                                alt={displayName} 
                                                className="rounded-circle"
                                                style={{ 
                                                    width: '150px', 
                                                    height: '150px', 
                                                    objectFit: 'cover',
                                                    display: imageLoaded ? 'block' : 'none'
                                                }}
                                                onLoad={handleImageLoad}
                                                onError={() => setImageLoaded(true)}
                                            />
                                            <div 
                                                className="position-absolute bottom-0 end-0 bg-primary rounded-circle d-flex align-items-center justify-content-center"
                                                style={{ width: '40px', height: '40px', cursor: loading ? 'not-allowed' : 'pointer' }}
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    if (!loading) {
                                                        triggerFileSelect();
                                                    }
                                                }}
                                            >
                                                {loading ? (
                                                    <span className="spinner-border spinner-border-sm text-white" role="status"></span>
                                                ) : (
                                                    <i className="ri-camera-fill text-white"></i>
                                                )}
                                            </div>
                                        </div>
                                        <div className="mt-3">
                                            <button
                                                type="button"
                                                className="btn btn-outline-primary btn-sm"
                                                onClick={triggerFileSelect}
                                                disabled={loading}
                                            >
                                                <i className="ri-upload-2-line me-1"></i>
                                                Change Photo
                                            </button>
                                            <p className="text-muted mt-2 mb-0">
                                                <small>Allowed JPG, GIF or PNG. Max size of 5MB</small>
                                            </p>
                                        </div>
                                    </div>
                                </div>

                                {/* Profile Details Section */}
                                <div className="col-lg-8">
                                    <div className="row">
                                        <div className="col-md-6">
                                            <div className="mb-3">
                                                <label className="form-label">First Name</label>
                                                <input
                                                    type="text"
                                                    className="form-control"
                                                    name="firstName"
                                                    value={profileData.firstName}
                                                    onChange={handleInputChange}
                                                    placeholder="Enter first name"
                                                    required
                                                />
                                            </div>
                                        </div>
                                        <div className="col-md-6">
                                            <div className="mb-3">
                                                <label className="form-label">Last Name</label>
                                                <input
                                                    type="text"
                                                    className="form-control"
                                                    name="lastName"
                                                    value={profileData.lastName}
                                                    onChange={handleInputChange}
                                                    placeholder="Enter last name"
                                                    required
                                                />
                                            </div>
                                        </div>
                                    </div>

                                    <div className="row">
                                        <div className="col-md-6">
                                            <div className="mb-3">
                                                <label className="form-label">Email Address</label>
                                                <input
                                                    type="email"
                                                    className="form-control"
                                                    name="email"
                                                    value={profileData.email}
                                                    onChange={handleInputChange}
                                                    placeholder="Enter email"
                                                    required
                                                />
                                            </div>
                                        </div>
                                        <div className="col-md-6">
                                            <div className="mb-3">
                                                <label className="form-label">Phone Number</label>
                                                <input
                                                    type="tel"
                                                    className="form-control"
                                                    name="phone"
                                                    value={profileData.phone}
                                                    onChange={handleInputChange}
                                                    placeholder="Enter phone number"
                                                />
                                            </div>
                                        </div>
                                    </div>

                                    <div className="mb-3">
                                        <label className="form-label">Bio</label>
                                        <textarea
                                            className="form-control"
                                            rows="4"
                                            name="bio"
                                            value={profileData.bio}
                                            onChange={handleInputChange}
                                            placeholder="Tell us about yourself..."
                                        ></textarea>
                                    </div>
                                </div>
                            </div>

                            <div className="d-flex justify-content-end gap-2 mt-4">
                                <button
                                    type="button"
                                    className="btn btn-light"
                                    onClick={handleCancel}
                                    disabled={loading}
                                >
                                    Cancel
                                </button>
                                <button
                                    type="submit"
                                    className="btn btn-primary"
                                    disabled={loading}
                                >
                                    {loading ? (
                                        <>
                                            <span className="spinner-border spinner-border-sm me-1" role="status"></span>
                                            Saving...
                                        </>
                                    ) : (
                                        <>
                                            <i className="ri-save-line me-1"></i>
                                            Save Changes
                                        </>
                                    )}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            </div>
        </div>
    );
}
